using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

// Now probe a type whose metadata may NOT be resolvable
// (using an options instance with no resolver at all)
var emptyOptions = new JsonSerializerOptions { TypeInfoResolver = null };
bool found2 = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Person) with no resolver: found={found2}, info={info2?.Type.Name ?? "(null)"}");

public record Person(string Name, int Age);

